import React from 'react';

const AporteDesarrollo = () => {
    return (
        <section>
            <h2>Aporte al desarrollo económico y social</h2>
            <p>
                El conocimiento sobre la dictadura de los hermanos Tinoco también puede contribuir al desarrollo económico y social, ya que comprender la historia política fortalece la institucionalidad democrática, la educación cívica y la participación ciudadana, todos ellos factores necesarios para el progreso de un país.
            </p>
            <p>
                Una sociedad que valora sus instituciones y comprende las consecuencias de los regímenes autoritarios tiende a generar mayores niveles de confianza pública, cohesión social y estabilidad política. Estas condiciones favorecen la seguridad jurídica, el clima de inversión y el desarrollo sostenible.
            </p>
            <p>
                Asimismo, la difusión de este tipo de contenidos puede promover iniciativas culturales y educativas vinculadas con la historia nacional, como proyectos pedagógicos, actividades comunitarias, producción audiovisual y propuestas de turismo histórico y cultural.
            </p>
        </section>
    );
};

export default AporteDesarrollo;
